// C++ — Fenwick Tree (1-indexed)

class FenwickTree {

    vector<int> tree;
    int n;

public:
    FenwickTree(int size) : n(size), tree(size + 1, 0) {}

    void update(int i, int delta) {
        for (; i <= n; i += i & (-i))
            tree[i] += delta;
    }

    int query(int i) {           // prefix sum [1, i]
        int sum = 0;
        for (; i > 0; i -= i & (-i))
            sum += tree[i];
        return sum;
    }

    int rangeQuery(int l, int r) {  // sum [l, r]
        return query(r) - query(l - 1);
    }
};

FenwickTree build(const vector<int>& arr) {
    int n = arr.size();
    FenwickTree ft(n);

    for (int i = 1; i <= n; i++) {
        ft.update(i, arr[i - 1]);
    }

    return ft;
}

long long countInversions(vector<int>& arr) {
    vector<int> vals = arr;
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());

    unordered_map<int, int> rank;
    for (int i = 0; i < vals.size(); i++)
        rank[vals[i]] = i + 1;

    FenwickTree ft(vals.size());
    long long inversions = 0;

    for (int i = arr.size() - 1; i >= 0; i--) {
        int r = rank[arr[i]];
        inversions += ft.query(r - 1); // smaller elements on the right
        ft.update(r, 1);               // mark current element as seen
    }

    return inversions;
}

void rangeUpdate(FenwickTree& ft, int l, int r, int val) {
    ft.update(l, val);        // start adding val from index l
    ft.update(r + 1, -val);   // stop adding after index r
}

int pointQuery(FenwickTree& ft, int i) {
    return ft.query(i);       // value at index i
}
